object Main {
  def main(args: Array[String]): Unit = {
    val nilaiMutu = Map("A" -> 4, "B" -> 3, "C" -> 2, "D" -> 1, "E" -> 0)
    val res = nilaiMutu.map { case (k, v) => k -> (v + 1) }
    res.toSeq.sortWith(_._1 < _._1).foreach { case (k, v) => println(s"$k -> $v") }
  }
}

object Main {
  def main(args: Array[String]): Unit = {
