object Main {
  def main(args: Array[String]): Unit = {
    val line = scala.io.StdIn.readLine()
    val angka = line.trim.split("\\s+").filter(_.nonEmpty).map(_.toInt).toList
    val frekuensi = angka.groupBy(x => x).map { case (k, v) => k -> v.length }
    frekuensi.toSeq.sortBy(_._1).foreach { case (k, v) => println(s"$k -> $v") }
  }
}

